WITH prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) AS prev_paid_at FROM payments), with_gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT s.id, s.order_id, s.method, s.status, s.new_group_flag, s.session_no, (SELECT AVG(t2.amount) FROM payments t2 WHERE t2.order_id = s.order_id) AS avg_payment_amount FROM sessionized s;
